def binary_search(s_l, c):
	low = 0
	high = len(s_l) - 1
	while low <= high:
		mid = (low + high) // 2
		if s_l[mid] == c:
			return -1
		elif s_l[mid] > c:
			high = mid - 1
		else:
			low = mid + 1
	return low
(a, b) = map(int, input().split())
l = list(map(int, input().split()))
l.sort()
for i in range(b):
	c = int(input())
	a = binary_search(l, c)
	if a == -1:
		print(0)
	elif a > len(l):
		print('POSITIVE')
	elif (len(l) - a) % 2 == 0:
		print('POSITIVE')
	else:
		print('NEGATIVE')
